using System.Net.Http.Json;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Simulated web search tool that returns results for a query.
/// Replace with a real search API (Bing, Google, Tavily) for production use.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    public static async Task<string> SearchAsync(string query)
    {
        // In production, replace with a real search API call:
        // - Bing Web Search API
        // - Google Custom Search API
        // - Tavily Search API
        //
        // Example with a real API:
        // var response = await HttpClient.GetFromJsonAsync<SearchResponse>(
        //     $"https://api.tavily.com/search?query={Uri.EscapeDataString(query)}&api_key={apiKey}");

        // Simulated search results for demonstration
        await Task.Delay(100); // Simulate network latency

        var results = new[]
        {
            new SearchResult(
                $"Overview of {query}",
                $"https://example.com/wiki/{Uri.EscapeDataString(query)}",
                $"A comprehensive overview covering the key aspects of {query}, including history, current state, and future directions."),
            new SearchResult(
                $"Latest developments in {query}",
                $"https://example.com/news/{Uri.EscapeDataString(query)}",
                $"Recent news and developments related to {query}. Experts weigh in on trends and implications for the field."),
            new SearchResult(
                $"Research papers on {query}",
                $"https://example.com/papers/{Uri.EscapeDataString(query)}",
                $"Academic research and publications exploring various dimensions of {query}, with peer-reviewed findings."),
        };

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }

    private record SearchResult(string Title, string Url, string Snippet);
}

namespace ResearchAgent;

/// <summary>
/// Service for managing research notes during an agent session.
/// </summary>
public sealed class NoteService
{
    private readonly List<ResearchNote> _notes = [];

    public string AddNote(string title, string content)
    {
        var note = new ResearchNote(title, content, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note saved: '{title}'";
    }

    public List<string> GetAllNotes()
    {
        return _notes
            .Select((n, i) => $"[{i + 1}] {n.Title}\n    {n.Content}\n    (Saved: {n.Timestamp:u})")
            .ToList();
    }

    public void Clear() => _notes.Clear();

    private record ResearchNote(string Title, string Content, DateTime Timestamp);
}

