    Console.Write("> ");
}

toolArgs.old_str:
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseOpenAIChatClient(
        builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<NoteService>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for information on a given query and returns relevant results."),
    AIFunctionFactory.Create(
        (string title, string content) => noteService.AddNote(title, content),
        "take_note",
        "Saves a research note with a title and content for later reference."),
    AIFunctionFactory.Create(
        () => noteService.GetAllNotes(),
        "get_notes",
        "Retrieves all saved research notes."),
};

var agent = new ChatClientAgent(chatClient,
    "You are a research assistant. When given a topic, search the web to gather information, " +
    "take notes on key findings, then provide a comprehensive summary. " +
    "Always search multiple aspects of the topic and take notes before summarizing.",
    tools);

Console.WriteLine("Research Agent Ready!");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    Console.WriteLine($"\nResearching: {input}\n");

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic thoroughly. Search the web for information, " +
            $"take notes on important findings, then provide a final summary.\n\nTopic: {input}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
    };

    await foreach (var message in agent.InvokeStreamingAsync(history, options))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n\n--- Research Notes ---");
    foreach (var note in noteService.GetAllNotes())
    {
        Console.WriteLine(note);
    }

    noteService.Clear();
    Console.WriteLine("\nEnter another topic (or 'quit' to exit):");
    Console.Write("> ");
}

