 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Hosting;
 using Microsoft.Agents.AI;
 using ResearchAgent;

 var builder = Host.CreateApplicationBuilder(args);

 var apiKey = builder.Configuration["AI:ApiKey"]
     ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

 var modelId = builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18";

 builder.Services.AddSingleton<NoteService>();
 builder.Services.AddChatClient(sp =>
     new OpenAI.OpenAIClient(apiKey)
         .GetChatClient(modelId)
         .AsIChatClient());

 using var host = builder.Build();

 var chatClient = host.Services.GetRequiredService<IChatClient>();
 var noteService = host.Services.GetRequiredService<NoteService>();

 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(
         (string query) => WebSearchTool.SearchAsync(query),
         "web_search",
         "Searches the web for information on a given query and returns relevant results."),
     AIFunctionFactory.Create(
         (string title, string content) => noteService.AddNote(title, content),
         "take_note",
         "Saves a research note with a title and content for later reference."),
     AIFunctionFactory.Create(
         () => noteService.GetAllNotes(),
         "get_notes",
         "Retrieves all saved research notes."),
 };

 var agent = new ChatClientAgent(
     chatClient,
     instructions: "You are a research assistant. When given a topic, search the web to gather " +
         "information from multiple angles, take notes on key findings, then provide a comprehensive " +
         "summary based on your notes. Always perform at least 2-3 searches on different aspects of " +
         "the topic and take a note after each search before writing the final summary.",
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     tools: tools);

 Console.WriteLine("╔══════════════════════════════════════╗");
 Console.WriteLine("║       Research Agent Ready!          ║");
 Console.WriteLine("╚══════════════════════════════════════╝");
 Console.WriteLine();
 Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
 Console.Write("> ");

 while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
 {
     if (string.IsNullOrWhiteSpace(input))
     {
         Console.Write("> ");
         continue;
     }

     Console.WriteLine($"\n🔍 Researching: {input}\n");
     noteService.Clear();

     var messages = new List<ChatMessage>
     {
         new(ChatRole.User,
             $"Research the following topic thoroughly. Search the web for information, " +
             $"take notes on important findings, then provide a final summary.\n\nTopic: {input}"),
     };

     var options = new ChatClientAgentRunOptions(new ChatOptions
     {
         Temperature = 0f,
         MaxOutputTokens = 2048,
     });

     var response = await agent.RunAsync(messages, null!, options);

     Console.WriteLine("\n📋 Agent Response:");
     Console.WriteLine(new string('─', 50));

     foreach (var message in response.Messages)
     {
         if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
         {
             Console.WriteLine(message.Text);
         }
     }

     Console.WriteLine();
     Console.WriteLine("📝 Research Notes Collected:");
     Console.WriteLine(new string('─', 50));
     var notes = noteService.GetAllNotes();
     if (notes.Count == 0)
     {
         Console.WriteLine("  (No notes were saved)");
     }
     else
     {
         foreach (var note in notes)
         {
             Console.WriteLine($"  {note}");
             Console.WriteLine();
         }
     }

     Console.WriteLine("\nEnter another topic (or 'quit' to exit):");
     Console.Write("> ");
 }

